static inline void story_frame(Framebuffer*f,int story,int shade){
 const unsigned char*s=story_pixels[(unsigned)story<3?story:0];
 for(int y=0;y<480;y++)for(int x=0;x<640;x++){
  unsigned v=s[(y>>1)*320+(x>>1)],r=v&224,g=(v&28)<<3,b=(v&3)<<6;
  f->pixels[y*640+x]=((r*(unsigned)shade/255)<<16)|((g*(unsigned)shade/255)<<8)|(b*(unsigned)shade/255);
 }
}
